class Group:
    def __init__(self, members: list[str]) -> None:
        if len(members) != len(set(members)):
            raise ValueError("Duplicate members are not allowed.")
        self.members = list(members)
        self._members_set = set(members)
        # Store balances in integer cents to avoid floating-point issues
        self._balances: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be positive.")

        if payer not in self._members_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            part_list = list(self.members)
        else:
            if not participants:
                raise ValueError("Participants list cannot be empty.")
            part_list = list(participants)
            for p in part_list:
                if p not in self._members_set:
                    raise ValueError(f"Participant '{p}' is not a group member.")

        # Convert total amount to integer cents
        total_cents = round(amount * 100)
        n = len(part_list)

        # Requirement 2:
        # Every other participant owes exactly the amount rounded down to the cent.
        # Leftover cents are borne by the payer.
        base_cents = total_cents // n
        remainder = total_cents - (base_cents * n)

        # Payer paid the full amount
        self._balances[payer] += total_cents

        if payer in part_list:
            # Payer owes base_cents + remainder
            # Other participants owe base_cents
            for p in part_list:
                if p == payer:
                    self._balances[p] -= base_cents + remainder
                else:
                    self._balances[p] -= base_cents
        else:
            # Payer is not among the participants.
            # All participants owe base_cents, and the remainder is borne by the payer.
            for p in part_list:
                self._balances[p] -= base_cents
            self._balances[payer] -= remainder

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances[m] / 100.0 for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Collect creditors (balance > 0) and debtors (balance < 0)
        creditors = []
        debtors = []
        for m in self.members:
            bal = self._balances[m]
            if bal > 0:
                creditors.append([m, bal])
            elif bal < 0:
                debtors.append([m, -bal])

        payments: list[tuple[str, str, float]] = []

        i, j = 0, 0
        while i < len(debtors) and j < len(creditors):
            debtor_name, debt_amt = debtors[i]
            creditor_name, cred_amt = creditors[j]

            settle_cents = min(debt_amt, cred_amt)
            if settle_cents > 0:
                payments.append((debtor_name, creditor_name, settle_cents / 100.0))

            debtors[i][1] -= settle_cents
            creditors[j][1] -= settle_cents

            if debtors[i][1] == 0:
                i += 1
            if creditors[j][1] == 0:
                j += 1

        return payments
